package com.ejemplo.alquileres.controller;
import com.ejemplo.alquileres.model.*; import com.ejemplo.alquileres.service.*; import com.ejemplo.alquileres.ui.*; import java.io.*; import java.math.*; import java.nio.file.Files; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*; import javafx.collections.*; import javafx.fxml.FXML; import javafx.scene.chart.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.FileChooser; import org.kordamp.ikonli.feather.Feather; import org.kordamp.ikonli.javafx.FontIcon; import org.springframework.stereotype.Component;
@Component public class DashboardController implements Refrescable {private final DashboardService dashboard;private final ReporteCobranzaService reporte;private final ReporteCobranzaExcelService excel;private final ReciboPdfService recibos;private final RecordatorioService recordatorios;private final Exportador exportador;private final Tareas tareas;private final Notificador aviso;private final MainController principal;private final Clock clock;@FXML private ComboBox<Periodo> periodo;@FXML private DatePicker desde,hasta;@FXML private Label actualizado,totalCobrado,variacion,detalleCartera,cartera,ocupacion,detalleOcupacion,porVencer,detalleVencer;@FXML private AreaChart<Number,Number> grafico;@FXML private NumberAxis ejeX,ejeY;@FXML private VBox top,ultimos,morosos,leyenda,vencimientos;@FXML private PieChart dona;@FXML private ProgressIndicator cargando;private List<String> etiquetas=List.of();
 public DashboardController(DashboardService d,ReporteCobranzaService r,ReporteCobranzaExcelService e,ReciboPdfService pdf,RecordatorioService rec,Exportador ex,Tareas t,Notificador n,MainController m,Clock c){dashboard=d;reporte=r;excel=e;recibos=pdf;recordatorios=rec;exportador=ex;tareas=t;aviso=n;principal=m;clock=c;}
 @FXML public void initialize(){periodo.setItems(FXCollections.observableArrayList(Periodo.values()));periodo.setValue(Periodo.ULTIMOS_30_DIAS);periodo.valueProperty().addListener((o,a,b)->{boolean p=b==Periodo.PERSONALIZADO;desde.setVisible(p);hasta.setVisible(p);desde.setManaged(p);hasta.setManaged(p);refrescar();});ejeX.setTickLabelFormatter(new javafx.util.StringConverter<>(){public String toString(Number n){int i=n.intValue();return i>=0&&i<etiquetas.size()?etiquetas.get(i):"";}public Number fromString(String s){return 0;}});ejeY.setTickLabelFormatter(new javafx.util.StringConverter<>(){public String toString(Number n){return "S/ "+String.format(java.util.Locale.US,"%,.0f",n.doubleValue());}public Number fromString(String s){return 0;}});}
 @Override public void refrescar(){if(periodo==null)return;cargando.setVisible(true);Periodo.Rango r=periodo.getValue().resolver(clock,desde.getValue(),hasta.getValue());tareas.ejecutar(()->new Datos(reporte.resumen(r),dashboard.resumen()),this::mostrar,e->{cargando.setVisible(false);aviso.error(mensaje(e));});}
 private void mostrar(Datos d){cargando.setVisible(false);ReporteCobranzaService.Resumen r=d.cobros;DashboardService.Resumen x=d.dashboard;totalCobrado.setText(Tablas.moneda(r.total()));if(r.variacion()==null){variacion.setText(r.total().signum()>0?"Nuevo":"▼ 0.0 %");variacion.getStyleClass().setAll("variacion",r.total().signum()>0?"positiva":"neutra");}else{boolean sube=r.variacion()>=0;variacion.setText((sube?"▲ ":"▼ ")+String.format(java.util.Locale.US,"%.1f %%",Math.abs(r.variacion())));variacion.getStyleClass().setAll("variacion",sube?"positiva":"negativa");}cartera.setText(Tablas.moneda(x.cartera().total()));detalleCartera.setText(x.cartera().cuotas()+" cuotas · "+x.cartera().arrendatarios()+" arrendatarios · "+String.format(java.util.Locale.US,"%.1f %%",x.cartera().porcentaje()));double pct=x.ocupacion().total()==0?0:100d*x.ocupacion().alquilados()/x.ocupacion().total();ocupacion.setText(String.format(java.util.Locale.US,"%.0f %%",pct));detalleOcupacion.setText(x.ocupacion().alquilados()+" de "+x.ocupacion().total()+" alquilados");porVencer.setText(String.valueOf(x.vencimientos().size()));detalleVencer.setText(x.vencimientos().isEmpty()?"Ninguno en los próximos 60 días":"Próximo: "+x.vencimientos().get(0).codigo()+" en "+x.vencimientos().get(0).dias()+" días");actualizado.setText("Resumen general · actualizado a las "+LocalTime.now(clock).format(DateTimeFormatter.ofPattern("HH:mm")));serie(r);ranking(r.top());pagos(r.ultimos());morosos(x.morosos());dona(x.ocupacion());vencimientos(x.vencimientos());}
 private void serie(ReporteCobranzaService.Resumen r){etiquetas=r.serie().stream().map(p->p.fecha().format(DateTimeFormatter.ofPattern(r.porMes()?"MMM yy":"dd MMM",new Locale("es","PE")))).toList();XYChart.Series<Number,Number>s=new XYChart.Series<>();double max=0;for(int i=0;i<r.serie().size();i++){double v=r.serie().get(i).total().doubleValue();s.getData().add(new XYChart.Data<>(i,v));max=Math.max(max,v);}grafico.getData().setAll(s);ejeX.setAutoRanging(false);ejeX.setLowerBound(0);ejeX.setUpperBound(Math.max(1,r.serie().size()-1));ejeX.setTickUnit(Math.max(1,Math.ceil(r.serie().size()/7d)));ejeY.setAutoRanging(false);ejeY.setLowerBound(0);ejeY.setUpperBound(max<=0?100:Math.ceil(max/5)*5);ejeY.setTickUnit(ejeY.getUpperBound()/5);}
 private void ranking(List<ReporteCobranzaService.IngresoInmueble> a){top.getChildren().clear();if(a.isEmpty()){vacio(top,"Sin cobros en el periodo.");return;}double m=a.get(0).importe().doubleValue();for(int i=0;i<a.size();i++){ReporteCobranzaService.IngresoInmueble p=a.get(i);Label n=new Label((i+1)+". "+p.nombre());Label v=new Label(Tablas.moneda(p.importe()));VBox texto=new VBox(2,n,v);ProgressBar b=new ProgressBar(m==0?0:p.importe().doubleValue()/m);b.setMaxWidth(Double.MAX_VALUE);texto.getChildren().add(b);texto.getStyleClass().add("ranking-fila");top.getChildren().add(texto);}}
 private void pagos(List<Pago> a){ultimos.getChildren().clear();if(a.isEmpty()){vacio(ultimos,"Sin cobros en el periodo.");return;}for(Pago p:a){Button pdf=new Button("PDF",new FontIcon(Feather.FILE_TEXT));pdf.setOnAction(e->pdf(p));Label l=new Label(p.getRecibo()+" · "+p.getArrendatarioNombre()+" · "+Tablas.moneda(p.getMontoTotal()));HBox f=new HBox(10,l,pdf);f.getStyleClass().add("venta-fila");ultimos.getChildren().add(f);}}
 private void morosos(List<DashboardService.Mora>a){morosos.getChildren().clear();if(a.isEmpty()){vacio(morosos,"Nadie en mora. ¡Buen trabajo!");return;}for(DashboardService.Mora m:a){Label l=new Label(m.arrendatario()+" · "+m.inmueble()+" · "+Tablas.moneda(m.deuda())+" · "+m.dias()+" días");HBox f=new HBox(10,l,Semaforo.crear(m.semaforo()));f.getStyleClass().add("venta-fila");morosos.getChildren().add(f);}}
 private void dona(DashboardService.Ocupacion o){ObservableList<PieChart.Data>d=FXCollections.observableArrayList();for(DashboardService.Tipo t:o.porTipo())d.add(new PieChart.Data(t.nombre(),t.cantidad()));dona.setData(d);leyenda.getChildren().clear();for(DashboardService.Tipo t:o.porTipo())leyenda.getChildren().add(new Label(t.nombre()+" · "+t.cantidad()));}
 private void vencimientos(List<DashboardService.Vencimiento>a){vencimientos.getChildren().clear();if(a.isEmpty()){vacio(vencimientos,"Sin contratos por vencer.");return;}for(DashboardService.Vencimiento v:a){Button b=new Button("Renovar");b.setOnAction(e->principal.irARenovarContrato(v.id()));Button avisar=new Button("Avisar");avisar.setOnAction(e->tareas.ejecutar(()->recordatorios.propuestaFinContrato(v.id()),p->DialogoRecordatorio.mostrar(ventana(),recordatorios,tareas,exportador,aviso,p,()->refrescar()),err->aviso.error(mensaje(err))));HBox f=new HBox(10,new Label(v.codigo()+" · "+v.inmueble()+" · "+v.arrendatario()+" · en "+v.dias()+" días"),b,avisar);f.getStyleClass().add("venta-fila");vencimientos.getChildren().add(f);}}
 private javafx.stage.Window ventana(){return periodo.getScene()==null?null:periodo.getScene().getWindow();} @FXML private void onActualizar(){refrescar();}@FXML private void onExportar(){Periodo.Rango r=periodo.getValue().resolver(clock,desde.getValue(),hasta.getValue());FileChooser f=new FileChooser();f.setInitialFileName("dashboard-"+r.desde()+"-"+r.hasta()+".xlsx");f.getExtensionFilters().add(new FileChooser.ExtensionFilter("Excel", "*.xlsx"));var destino=f.showSaveDialog(periodo.getScene().getWindow());if(destino==null)return;tareas.ejecutar(()->{try{Datos d=new Datos(reporte.resumen(r),dashboard.resumen());Files.write(destino.toPath(),excel.generar(d.cobros,d.dashboard));return null;}catch(IOException e){throw new IllegalStateException("No se pudo guardar el Excel.",e);}},v->aviso.info("Excel generado."),e->aviso.error(mensaje(e)));}@FXML private void onVerPagos(){principal.irA("pagos");}private void pdf(Pago p){tareas.ejecutar(()->recibos.generar(p.getId()),b->{try{File x=File.createTempFile(p.getRecibo(),".pdf");Files.write(x.toPath(),b);java.awt.Desktop.getDesktop().open(x);}catch(Exception e){aviso.error("No se pudo abrir el recibo.");}},e->aviso.error(mensaje(e)));}private void vacio(VBox b,String t){Label l=new Label(t);l.getStyleClass().add("texto-vacio");b.getChildren().add(l);}private String mensaje(Throwable e){return e.getCause()!=null&&e.getCause().getMessage()!=null?e.getCause().getMessage():e.getMessage();}private record Datos(ReporteCobranzaService.Resumen cobros,DashboardService.Resumen dashboard){}}